package com.Diaz_Capital_Group.Diaz_Capital_Group.Service;import com.Diaz_Capital_Group.Diaz_Capital_Group.Dto.CostumerDto;import com.Diaz_Capital_Group.Diaz_Capital_Group.Entity.CostumerEntity;import com.Diaz_Capital_Group.Diaz_Capital_Group.Repository.CostumerRepo;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.util.List;import java.util.Optional;@Servicepublic class CostumerServiceImpl implements ICostumerService{    @Autowired    private CostumerRepo costumerRepo;    @Override    public  Optional<CostumerDto> getCu(String cu) {        return costumerRepo.findByCu(cu).stream().map(CostumerEntity::getData).findFirst();    }    @Override    public List<CostumerDto> getAll() {        return costumerRepo.findAll().stream().map(CostumerEntity::getData).toList();    }    @Override    public Optional<CostumerDto> getByID(String id) {        return costumerRepo.findById(id).stream().map(CostumerEntity::getData).findFirst();    }    @Override    public CostumerDto add(CostumerDto costumerDto) {        CostumerEntity costumerEntity = new CostumerEntity();        costumerEntity.setData(costumerDto);        return costumerRepo.save(costumerEntity).getData();    }    @Override    public CostumerDto upDate(CostumerDto costumerDto) {        Optional<CostumerEntity> costumerEntity = costumerRepo.findById(costumerDto.getId())                .stream().findFirst();        if (costumerEntity.isPresent()){            CostumerEntity costumer = costumerEntity.get();            costumer.setName(costumerDto.getName());            costumer.setAddress(costumerDto.getAddress());            costumer.setMobile(costumerDto.getMobile());             return costumerRepo.save(costumer).getData();        }else{            throw new RuntimeException("Usuario No encontrado");        }    }    @Override    public void delete(String id) {        Optional<CostumerEntity>  buscar = costumerRepo.findById(id);        if (buscar.isPresent()){            costumerRepo.deleteById(id);        }else{            throw new RuntimeException("Usuario No encontrado");        }    }}